#include <string.h>
#include <stdio.h>
#include <stdlib.h>

extern int fuzz_parse_http_request(const unsigned char *data, size_t size);

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <poc_file>\n", argv[0]);
        return 1;
    }
    FILE *f = fopen(argv[1], "rb");
    if (!f) { perror("fopen"); return 1; }
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    unsigned char *buf = malloc(sz);
    fread(buf, 1, sz, f);
    fclose(f);
    int ret = fuzz_parse_http_request(buf, sz);
    printf("fuzz_parse_http_request returned: %d\n", ret);
    free(buf);
    return 0;
}
EOF
echo "Created test harness"

